using System;
using System.Collections.Generic;
using UnityEngine;

namespace Framework.AI.Scheduling
{
    /// <summary>
    /// 複数のエージェントの間隔更新と処理負荷を管理する。
    /// </summary>
    /// <remarks>
    /// エージェント固有の行動内容には関与しない。
    /// メインスレッドからの利用を想定する。
    /// </remarks>
    [DisallowMultipleComponent]
    public sealed class AgentUpdateManager : MonoBehaviour
    {
        /// <summary>
        /// 登録されたエージェントの更新管理情報。
        /// </summary>
        private sealed class AgentEntry
        {
            /// <summary>
            /// 更新対象のエージェント。
            /// </summary>
            public IAgentTickable Agent;

            /// <summary>
            /// 個体固有の更新間隔。単位は秒。
            /// </summary>
            public float Interval;

            /// <summary>
            /// 前回更新した管理時間。
            /// </summary>
            public double LastUpdateTime;

            /// <summary>
            /// 次回更新予定の管理時間。
            /// </summary>
            public double NextUpdateTime;

            /// <summary>
            /// 更新要求が登録されているかどうか。
            /// </summary>
            public bool UpdateRequested;

            /// <summary>
            /// 登録解除されているかどうか。
            /// </summary>
            public bool IsRemoved;
        }

        [Header("更新設定")]
        [SerializeField]
        [Tooltip("更新間隔と処理負荷分散の設定。")]
        private AgentUpdateSettings settings =
            new AgentUpdateSettings();

        [SerializeField]
        [Tooltip("UnityのUpdateから自動的に更新する。")]
        private bool autoUpdate = true;

        [Header("実行状態")]
        [SerializeField]
        [Tooltip("更新処理を一時停止しているかどうか。")]
        private bool isPaused;

        [SerializeField]
        [Tooltip("現在登録されているエージェント数。")]
        private int registeredCount;

        [SerializeField]
        [Tooltip("直前の管理更新で実行した件数。")]
        private int lastTickUpdateCount;

        [SerializeField]
        [Tooltip("これまでの累計更新件数。")]
        private long totalUpdateCount;

        /// <summary>
        /// 登録されたエージェントの一覧。
        /// </summary>
        private readonly List<AgentEntry> entries =
            new List<AgentEntry>();

        /// <summary>
        /// 次回の走査開始位置。
        /// </summary>
        private int nextIndex;

        /// <summary>
        /// 管理開始からの経過時間。単位は秒。
        /// </summary>
        private double elapsedTime;

        /// <summary>
        /// 初回更新の分散に使用する登録番号。
        /// </summary>
        private long registrationSequence;

        /// <summary>
        /// 現在更新処理を実行しているかどうか。
        /// </summary>
        private bool isTicking;

        /// <summary>
        /// 削除済み登録情報が残っているかどうか。
        /// </summary>
        private bool hasRemovedEntries;

        /// <summary>
        /// 初回更新の分散に使用する黄金比由来の定数。
        /// </summary>
        private const double StaggerFactor =
            0.6180339887498949d;

        /// <summary>
        /// 現在の更新設定を取得する。
        /// </summary>
        public AgentUpdateSettings Settings => settings;

        /// <summary>
        /// 登録済みエージェント数を取得する。
        /// </summary>
        public int RegisteredCount => registeredCount;

        /// <summary>
        /// 直前の管理更新における実行件数を取得する。
        /// </summary>
        public int LastTickUpdateCount =>
            lastTickUpdateCount;

        /// <summary>
        /// 累計更新件数を取得する。
        /// </summary>
        public long TotalUpdateCount =>
            totalUpdateCount;

        /// <summary>
        /// 管理開始からの経過時間を取得する。単位は秒。
        /// </summary>
        public double ElapsedTime => elapsedTime;

        /// <summary>
        /// 更新処理が一時停止中かどうかを取得する。
        /// </summary>
        public bool IsPaused => isPaused;

        /// <summary>
        /// 自動更新の有効状態を取得または設定する。
        /// </summary>
        public bool AutoUpdate
        {
            get => autoUpdate;
            set => autoUpdate = value;
        }

        /// <summary>
        /// 初期設定を検証する。
        /// </summary>
        private void Awake()
        {
            if (settings == null)
            {
                settings = new AgentUpdateSettings();
            }

            settings.Validate();
        }

        /// <summary>
        /// Unityのフレーム更新から管理処理を実行する。
        /// </summary>
        private void Update()
        {
            if (!autoUpdate)
            {
                return;
            }

            float deltaTime = settings.UseUnscaledTime
                ? Time.unscaledDeltaTime
                : Time.deltaTime;

            Tick(deltaTime);
        }

        /// <summary>
        /// 破棄時に登録情報を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Clear();
        }

        /// <summary>
        /// 更新管理設定を変更する。
        /// </summary>
        /// <param name="newSettings">新しい更新設定</param>
        /// <remarks>
        /// 登録済みエージェントの個別更新間隔は維持する。
        /// 標準更新間隔は以降の登録時に使用する。
        /// </remarks>
        /// <exception cref="ArgumentNullException">
        /// 設定がnullの場合に発生する。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 更新処理中の場合に発生する。
        /// </exception>
        public void Configure(
            AgentUpdateSettings newSettings)
        {
            if (isTicking)
            {
                throw new InvalidOperationException(
                    "更新処理中は設定を変更できません。");
            }

            if (newSettings == null)
            {
                throw new ArgumentNullException(
                    nameof(newSettings));
            }

            newSettings.Validate();

            settings = newSettings;
        }

        /// <summary>
        /// 標準更新間隔を使用してエージェントを登録する。
        /// </summary>
        /// <param name="agent">登録対象</param>
        /// <returns>登録に成功した場合はtrue</returns>
        public bool TryRegister(IAgentTickable agent)
        {
            return TryRegister(
                agent,
                settings.UpdateInterval);
        }

        /// <summary>
        /// 個別の更新間隔を指定してエージェントを登録する。
        /// </summary>
        /// <param name="agent">登録対象</param>
        /// <param name="interval">更新間隔。単位は秒</param>
        /// <returns>
        /// 登録に成功した場合はtrue。
        /// 登録済みの場合はfalse。
        /// </returns>
        /// <exception cref="ArgumentNullException">
        /// エージェントがnullの場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 更新間隔が不正な場合に発生する。
        /// </exception>
        public bool TryRegister(
            IAgentTickable agent,
            float interval)
        {
            if (IsInvalidAgent(agent))
            {
                throw new ArgumentNullException(
                    nameof(agent));
            }

            ValidateInterval(interval);

            if (FindEntry(agent) != null)
            {
                return false;
            }

            // 初回更新までの待機時間。
            double initialDelay = interval;

            if (settings.StaggerInitialUpdate)
            {
                // 登録順に更新タイミングが集中しないよう分散する。
                double phase =
                    (registrationSequence * StaggerFactor) % 1d;

                initialDelay = interval * phase;
            }

            registrationSequence++;

            var entry = new AgentEntry
            {
                Agent = agent,
                Interval = interval,
                LastUpdateTime = elapsedTime,
                NextUpdateTime = elapsedTime + initialDelay,
                UpdateRequested = false,
                IsRemoved = false
            };

            entries.Add(entry);

            registeredCount++;

            return true;
        }

        /// <summary>
        /// エージェントが登録されているか判定する。
        /// </summary>
        /// <param name="agent">検索対象</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool Contains(IAgentTickable agent)
        {
            return FindEntry(agent) != null;
        }

        /// <summary>
        /// 指定されたエージェントの登録を解除する。
        /// </summary>
        /// <param name="agent">登録解除対象</param>
        /// <returns>登録解除に成功した場合はtrue</returns>
        public bool TryUnregister(IAgentTickable agent)
        {
            AgentEntry entry = FindEntry(agent);

            if (entry == null)
            {
                return false;
            }

            MarkRemoved(entry);

            // 更新処理中の一覧変更を回避する。
            if (!isTicking)
            {
                CompactEntries();
            }

            return true;
        }

        /// <summary>
        /// 指定されたエージェントの更新間隔を変更する。
        /// </summary>
        /// <param name="agent">変更対象</param>
        /// <param name="interval">新しい更新間隔。単位は秒</param>
        /// <returns>変更対象が登録済みの場合はtrue</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 更新間隔が不正な場合に発生する。
        /// </exception>
        public bool TrySetInterval(
            IAgentTickable agent,
            float interval)
        {
            ValidateInterval(interval);

            AgentEntry entry = FindEntry(agent);

            if (entry == null)
            {
                return false;
            }

            entry.Interval = interval;

            entry.NextUpdateTime =
                entry.LastUpdateTime + interval;

            return true;
        }

        /// <summary>
        /// 通常の更新予定を待たずに更新するよう要求する。
        /// </summary>
        /// <param name="agent">更新要求対象</param>
        /// <returns>要求対象が登録済みの場合はtrue</returns>
        /// <remarks>
        /// 更新処理を直接実行するものではない。
        /// 最大実行件数の制限は維持される。
        /// 複数の要求は一回の更新要求としてまとめられる。
        /// </remarks>
        public bool RequestUpdate(IAgentTickable agent)
        {
            AgentEntry entry = FindEntry(agent);

            if (entry == null)
            {
                return false;
            }

            entry.UpdateRequested = true;

            return true;
        }

        /// <summary>
        /// 更新処理を一時停止または再開する。
        /// </summary>
        /// <param name="paused">一時停止する場合はtrue</param>
        public void SetPaused(bool paused)
        {
            isPaused = paused;
        }

        /// <summary>
        /// 更新処理を一時停止する。
        /// </summary>
        public void Pause()
        {
            SetPaused(true);
        }

        /// <summary>
        /// 更新処理を再開する。
        /// </summary>
        public void Resume()
        {
            SetPaused(false);
        }

        /// <summary>
        /// エージェントの間隔更新を実行する。
        /// </summary>
        /// <param name="deltaTime">経過時間。単位は秒</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 経過時間が不正な場合に発生する。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 更新処理中に再度呼び出された場合に発生する。
        /// </exception>
        public void Tick(float deltaTime)
        {
            if (float.IsNaN(deltaTime) ||
                float.IsInfinity(deltaTime) ||
                deltaTime < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(deltaTime));
            }

            if (isTicking)
            {
                throw new InvalidOperationException(
                    "更新処理中にTickを再実行できません。");
            }

            lastTickUpdateCount = 0;

            if (isPaused || deltaTime == 0f)
            {
                return;
            }

            elapsedTime += deltaTime;

            if (entries.Count == 0)
            {
                return;
            }

            isTicking = true;

            try
            {
                ExecuteScheduledUpdates();
            }
            finally
            {
                isTicking = false;

                if (hasRemovedEntries)
                {
                    CompactEntries();
                }
            }
        }

        /// <summary>
        /// 更新予定に到達したエージェントを分散実行する。
        /// </summary>
        private void ExecuteScheduledUpdates()
        {
            // 更新中に新規登録された対象は次回から処理する。
            int scanLimit = entries.Count;

            int scannedCount = 0;

            int maxUpdates = settings.MaxUpdatesPerTick;

            while (scannedCount < scanLimit &&
                   lastTickUpdateCount < maxUpdates &&
                   !isPaused)
            {
                if (nextIndex >= scanLimit)
                {
                    nextIndex = 0;
                }

                AgentEntry entry = entries[nextIndex];

                // 次のエージェントから走査を再開できるようにする。
                nextIndex++;

                scannedCount++;

                if (entry.IsRemoved)
                {
                    continue;
                }

                if (IsInvalidAgent(entry.Agent))
                {
                    MarkRemoved(entry);

                    continue;
                }

                if (!entry.Agent.IsTickEnabled)
                {
                    continue;
                }

                bool isDue =
                    elapsedTime >= entry.NextUpdateTime;

                if (!isDue && !entry.UpdateRequested)
                {
                    continue;
                }

                ExecuteAgent(entry);
            }
        }

        /// <summary>
        /// 単一エージェントの更新処理を実行する。
        /// </summary>
        /// <param name="entry">更新対象の管理情報</param>
        private void ExecuteAgent(AgentEntry entry)
        {
            // 前回の実行からの実際の経過時間を算出する。
            double elapsed =
                elapsedTime - entry.LastUpdateTime;

            float agentDeltaTime =
                (float)Math.Min(elapsed, float.MaxValue);

            // コールバック内からの再要求を保持できるよう、
            // 実行前に現在の更新要求を解除する。
            entry.UpdateRequested = false;

            entry.LastUpdateTime = elapsedTime;

            entry.NextUpdateTime =
                elapsedTime + entry.Interval;

            lastTickUpdateCount++;

            totalUpdateCount++;

            try
            {
                entry.Agent.Tick(agentDeltaTime);
            }
            catch (Exception exception)
            {
                // 異常のあるエージェントを登録解除し、
                // 他のエージェントの更新を継続する。
                MarkRemoved(entry);

                Debug.LogException(exception, this);
            }
        }

        /// <summary>
        /// 指定されたエージェントの登録情報を検索する。
        /// </summary>
        /// <param name="agent">検索対象</param>
        /// <returns>登録情報。未登録の場合はnull</returns>
        private AgentEntry FindEntry(IAgentTickable agent)
        {
            for (int i = 0; i < entries.Count; i++)
            {
                AgentEntry entry = entries[i];

                if (!entry.IsRemoved &&
                    ReferenceEquals(entry.Agent, agent))
                {
                    return entry;
                }
            }

            return null;
        }

        /// <summary>
        /// 指定された登録情報を削除済みとして扱う。
        /// </summary>
        /// <param name="entry">削除対象</param>
        private void MarkRemoved(AgentEntry entry)
        {
            if (entry.IsRemoved)
            {
                return;
            }

            entry.IsRemoved = true;

            registeredCount--;

            hasRemovedEntries = true;
        }

        /// <summary>
        /// 削除済みの登録情報を一覧から除去する。
        /// </summary>
        private void CompactEntries()
        {
            // 走査位置を補正しながら削除済み情報を除去する。
            for (int i = entries.Count - 1; i >= 0; i--)
            {
                if (!entries[i].IsRemoved)
                {
                    continue;
                }

                if (i < nextIndex)
                {
                    nextIndex--;
                }

                entries.RemoveAt(i);
            }

            if (nextIndex >= entries.Count)
            {
                nextIndex = 0;
            }

            hasRemovedEntries = false;
        }

        /// <summary>
        /// すべてのエージェントの登録を解除する。
        /// </summary>
        public void Clear()
        {
            if (isTicking)
            {
                // 更新中は物理的な削除を行わない。
                for (int i = 0; i < entries.Count; i++)
                {
                    MarkRemoved(entries[i]);
                }

                return;
            }

            entries.Clear();

            registeredCount = 0;

            nextIndex = 0;

            hasRemovedEntries = false;
        }

        /// <summary>
        /// 更新統計情報をリセットする。
        /// </summary>
        /// <remarks>
        /// 登録情報と更新予定時間は維持する。
        /// </remarks>
        public void ResetStatistics()
        {
            if (isTicking)
            {
                throw new InvalidOperationException(
                    "更新処理中は統計をリセットできません。");
            }

            lastTickUpdateCount = 0;

            totalUpdateCount = 0;
        }

        /// <summary>
        /// エージェントが無効な参照かどうか判定する。
        /// </summary>
        /// <param name="agent">判定対象</param>
        /// <returns>無効な参照の場合はtrue</returns>
        private static bool IsInvalidAgent(
            IAgentTickable agent)
        {
            if (ReferenceEquals(agent, null))
            {
                return true;
            }

            // Unityオブジェクトの破棄済み参照にも対応する。
            if (agent is UnityEngine.Object unityObject)
            {
                return unityObject == null;
            }

            return false;
        }

        /// <summary>
        /// 更新間隔が有効であることを検証する。
        /// </summary>
        /// <param name="interval">更新間隔。単位は秒</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 更新間隔が不正な場合に発生する。
        /// </exception>
        private static void ValidateInterval(float interval)
        {
            if (float.IsNaN(interval) ||
                float.IsInfinity(interval) ||
                interval < 0.001f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(interval),
                    "更新間隔は0.001秒以上である必要があります。");
            }
        }
    }
}
